function diff(ctx: SlashContext): SlashOutcome {
  const cwd = workspace(ctx);
  { const info = getGitInfo(cwd); if (!info.isRepo) return reply("diff", info.refusal ?? NOT_A_REPO, false); }
  try {
    const out = git(cwd, ["diff", "--no-color"]);
